// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {MONEY_BOX} from "../src/MONEY_BOX.sol";

contract InvMutTest is Test {
    MONEY_BOX c;
    function setUp() public { c = new MONEY_BOX(); }

    function testFuzz_property(uint256 firstVal, uint256 secondVal, address caller) public {
        vm.assume(caller != address(0));
        firstVal = bound(firstVal, 1, type(uint256).max/4);
        secondVal = bound(secondVal, 1, type(uint256).max/4);

        vm.deal(caller, 1 ether);

        vm.prank(caller);
        c.SetMinSum(firstVal);

        vm.prank(caller);
        c.SetMinSum(secondVal);

        assertTrue(c.MinSum() == secondVal);
    }
}
